// Distance from the core face to the facade on the narrow side of each tower plate.
function run(input) {
  const depth = input.towers.map((t) => {
    const v = t.values
    if (!(v.minSide > 0) || !(v.coreArea >= 0)) return null
    return (v.minSide - Math.sqrt(v.coreArea)) / 2
  })
  const known = depth.filter((d) => d !== null)
  return { core_to_facade: depth, deepest: known.length ? Math.max(...known) : null }
}
